`src/envs/dev/infra/logs.ts`
```typescript
/**
 * dev environment — application logs bucket and its reader identity.
 *
 * Discovered by `chant build src/envs/dev/infra` alongside `main.ts`.
 * SecureBucket already pins versioning, encryption, and the public-access
 * block unconditionally, so there is nothing to add here for criterion 1.
 */

import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";
const LOGS_BUCKET = "myapp-logs-dev";

export const logs = SecureBucket({
  name: LOGS_BUCKET,
  env: ENV,
  region: REGION,
  component: "logs",
});

// Scoped to the logs bucket only. `s3:GetObject` comes from the baseline
// reader policy; `s3:PutObject` is added by enumeration, never a wildcard.
export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: LOGS_BUCKET,
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  component: "logs",
});
```

